 "content": "def transform(grid):
    """Restore 2-valued occlusions from the grid's dihedral symmetry."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    if h != w:
        raise ValueError("expected square symmetry grid")
    n = h
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                orbit = {
                    (r, c), (r, n - 1 - c), (n - 1 - r, c),
                    (n - 1 - r, n - 1 - c), (c, r),
                    (c, n - 1 - r), (n - 1 - c, r),
                    (n - 1 - c, n - 1 - r),
                }
                values = [grid[rr][cc] for rr, cc in orbit if grid[rr][cc] != 2]
                if not values:
                    raise ValueError("masked symmetry orbit has no visible source")
                if any(v != values[0] for v in values):
                    raise ValueError("visible symmetry orbit is inconsistent")
                out[r][c] = values[0]
    return out
